section.script:
// 
document.addEventListener('DOMContentLoaded', function() {
    var galleryModal = document.getElementById('galleryModal');
    var galleryCarousel = document.getElementById('galleryCarousel');
    var galleryCounter = document.getElementById('galleryCounter');
    var totalSlides = <t t-esc="len(gals)"/>;
    if (galleryModal && galleryCarousel) {
        var carousel = new bootstrap.Carousel(galleryCarousel);
        galleryModal.addEventListener('show.bs.modal', function (event) {
            var button = event.relatedTarget;
            var index = parseInt(button.getAttribute('data-index'));
            carousel.to(index);
            if (galleryCounter) { galleryCounter.innerText = (index + 1) + '/' + totalSlides; }
        });
        galleryCarousel.addEventListener('slid.bs.carousel', function () {
            var activeItem = galleryCarousel.querySelector('.carousel-item.active');
            var index = Array.from(galleryCarousel.querySelectorAll('.carousel-item')).indexOf(activeItem);
            if (galleryCounter) { galleryCounter.innerText = (index + 1) + '/' + totalSlides; }
        });
    }
});
//

// 
function scrollPlans(direction) {
    const activePane = document.querySelector('.tab-pane.active .plans-scroll-container');
    if(activePane) {
        const scrollAmount = 380;
        if(direction === 'left') activePane.scrollLeft -= scrollAmount;
        else activePane.scrollLeft += scrollAmount;
    }
}
