div.script:
        // 
            function shareProperty() {
                var url = window.location.href;
                if (navigator.share) {
                    navigator.share({ title: document.title, url: url }).catch(function(err) { console.error('Share failed:', err); });
                } else {
                    var textArea = document.createElement("textarea");
                    textArea.value = url; document.body.appendChild(textArea); textArea.select();
                    try { document.execCommand('copy'); alert('Property link copied to clipboard!'); } catch (err) { console.error('Copy failed:', err); }
                    document.body.removeChild(textArea);
                }
            }

          function toggleWishlist(propertyId) {
    fetch('/api/realestate_core/wishlist/toggle', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            jsonrpc: "2.0",
            method: "call",
            params: {
                property_id: propertyId
            }
        })
    })
    .then(response => response.json())
    .then(data => {
        // Fallback: If session expired while on the page, force login redirect
        if (data.error) {
            window.location.href = '/web/login?redirect=' + encodeURIComponent(window.location.href);
            return;
        }

        if (data.result && data.result.status === 'success') {
            const btn = document.getElementById('btn-save-property');
            const icon = document.getElementById('icon-save-property');

            if (data.result.is_wishlisted) {
                btn.classList.add('active-wishlist');
                icon.classList.remove('fa-heart-o');
                icon.classList.add('fa-heart');
            } else {
                btn.classList.remove('active-wishlist');
                icon.classList.remove('fa-heart');
                icon.classList.add('fa-heart-o');
            }
        } else {
            console.error('Error toggling wishlist:', data);
            alert(data.result?.message || 'Failed to update wishlist.');
        }
    })
    .catch(error => console.error('Fetch error:', error));
}
